function ensureDataTableViewer(){
  if(document.getElementById('dataTableViewerModal')) return;
  const modal = document.createElement('div');
  modal.id = 'dataTableViewerModal';
  modal.className = 'data-viewer-modal';
  modal.setAttribute('aria-hidden','true');
  modal.innerHTML = `
    <div class="data-viewer-backdrop" data-data-viewer-close="1"></div>
    <div class="data-viewer-dialog" role="dialog" aria-modal="true" aria-labelledby="dataViewerTitle">
      <div class="data-viewer-head">
        <div>
          <div class="data-viewer-kicker">Aktif veri dosyası</div>
          <h3 id="dataViewerTitle">Veri tablosu</h3>
          <div class="data-viewer-path" id="dataViewerPath">-</div>
        </div>
        <button type="button" class="data-viewer-close" data-data-viewer-close="1" aria-label="Kapat">Ã—</button>
      </div>
      <div class="data-viewer-toolbar">
        <input type="search" id="dataViewerSearch" class="data-viewer-search" placeholder="Tabloda ara: ürün, parsel, köy, ay..." />
        <button type="button" id="dataViewerShowAll" class="btn-secondary">Tüm satırları göster</button>
        <button type="button" id="dataViewerCopyHead" class="btn-secondary">Başlıkları kopyala</button>
      </div>
      <div class="data-viewer-summary" id="dataViewerSummary">Dosya seçilmedi.</div>
      <div class="data-viewer-table-wrap" id="dataViewerTableWrap"></div>
    </div>`;
  document.body.appendChild(modal);

  modal.addEventListener('click', (ev)=>{
    const closeEl = ev.target && ev.target.closest ? ev.target.closest('[data-data-viewer-close]') : null;
    if(closeEl) closeDataTableViewer();
  });
  document.addEventListener('keydown', (ev)=>{
    if(ev.key === 'Escape' && modal.classList.contains('is-open')) closeDataTableViewer();
  });

  const search = modal.querySelector('#dataViewerSearch');
  if(search){
    search.addEventListener('input', ()=>{
      __dataViewerState.filter = search.value || '';
      __dataViewerState.showAll = false;
      renderDataViewerTable();
    });
  }
  const showAllBtn = modal.querySelector('#dataViewerShowAll');
  if(showAllBtn){
    showAllBtn.addEventListener('click', ()=>{
      __dataViewerState.showAll = !__dataViewerState.showAll;
      renderDataViewerTable();
    });
  }
  const copyBtn = modal.querySelector('#dataViewerCopyHead');
  if(copyBtn){
    copyBtn.addEventListener('click', async ()=>{
      try{
        await navigator.clipboard.writeText((__dataViewerState.headers || []).join('\t'));
        copyBtn.textContent = 'Kopyalandı';
        setTimeout(()=>{ copyBtn.textContent = 'Başlıkları kopyala'; }, 1200);
      }catch(_e){}
    });
  }

  document.addEventListener('click', (ev)=>{
    const btn = ev.target && ev.target.closest ? ev.target.closest('[data-file-url]') : null;
    if(!btn) return;
    ev.preventDefault();
    openDataFileViewer(btn.dataset.fileUrl, btn.dataset.fileLabel, btn.dataset.filePath);
  });
}

function closeDataTableViewer(){
  const modal = document.getElementById('dataTableViewerModal');
  if(!modal) return;
  modal.classList.remove('is-open');
  modal.setAttribute('aria-hidden','true');
}

async function fetchTextWithFallbackV66(url){
  const candidates = [];
  const u = String(url||'').trim();
  if(!u) throw new Error('Dosya yolu boş.');
  candidates.push(u);
  if(u.startsWith('data/')) candidates.push('/' + u);
  if(u.startsWith('/data/')) candidates.push(u.slice(1));
  let lastErr = null;
  for(const c of Array.from(new Set(candidates))){
    try{
      const r = await fetch(c, {cache:'no-store'});
      if(r.ok) return await r.text();
      lastErr = new Error(`HTTP ${r.status} - ${c}`);
    }catch(e){ lastErr = e; }
  }
  throw lastErr || new Error('Dosya okunamadı.');
}

function parseCsvRobustV66(text){
  const rows = [];
  let row = [], cell = '', inQuotes = false;
  const src = String(text || '').replace(/^\uFEFF/, '');
  const firstLine = (src.split(/\r?\n/)[0] || '');
  const counts = {
    ';': (firstLine.match(/;/g) || []).length,
    ',': (firstLine.match(/,/g) || []).length,
    '\t': (firstLine.match(/\t/g) || []).length
  };
  const delim = (counts['\t'] > counts[';'] && counts['\t'] > counts[',']) ? '\t' : (counts[';'] >= counts[','] ? ';' : ',');
  for(let i=0; i<src.length; i++){
    const ch = src[i];
    const next = src[i+1];
    if(ch === '"'){
      if(inQuotes && next === '"'){ cell += '"'; i++; }
      else inQuotes = !inQuotes;
    }else if(ch === delim && !inQuotes){
      row.push(cell); cell = '';
    }else if((ch === '\n' || ch === '\r') && !inQuotes){
      if(ch === '\r' && next === '\n') i++;
      row.push(cell); cell = '';
      if(row.some(x=>String(x).trim()!=='')) rows.push(row);
      row = [];
    }else{
      cell += ch;
    }
  }
  row.push(cell);
  if(row.some(x=>String(x).trim()!=='')) rows.push(row);
  if(!rows.length) return {headers:[], rows:[]};

  // İlk satırda yanlış ayraç algısı olduysa tekrar basit ayraç tahminiyle böl.
  let header = rows[0].map(x=>String(x||'').trim());
  if(header.length === 1){
    const firstLine = String(text||'').split(/\r?\n/)[0] || '';
    const delim = firstLine.includes(';') && !firstLine.includes(',') ? ';' : (firstLine.includes('\t') ? '\t' : ',');
    const simple = String(text||'').split(/\r?\n/).filter(x=>x.trim()).map(line=>line.split(delim));
    header = (simple[0]||[]).map(x=>String(x||'').trim());
    const dataRows = simple.slice(1).map(cols=>{
      const obj = {};
      header.forEach((h,i)=> obj[h || `kolon_${i+1}`] = String(cols[i] ?? '').trim());
      return obj;
    });
    return {headers: header.map((h,i)=>h || `kolon_${i+1}`), rows:dataRows};
  }

  header = header.map((h,i)=>h || `kolon_${i+1}`);
  const dataRows = rows.slice(1).map(cols=>{
    const obj = {};
    header.forEach((h,i)=> obj[h] = String(cols[i] ?? '').trim());
    return obj;
  });
  return {headers: header, rows: dataRows};
}

function flattenObjectV66(obj, prefix='', out={}){
  if(obj === null || obj === undefined){
    out[prefix || 'value'] = '';
    return out;
  }
  if(Array.isArray(obj)){
    if(!prefix && obj.every(x=>x && typeof x === 'object' && !Array.isArray(x))){
      return obj;
    }
    obj.slice(0,20).forEach((v,i)=> flattenObjectV66(v, prefix ? `${prefix}.${i}` : String(i), out));
    return out;
  }
  if(typeof obj === 'object'){
    const entries = Object.entries(obj);
    if(!entries.length && prefix) out[prefix] = '';
    for(const [k,v] of entries){
      const key = prefix ? `${prefix}.${k}` : k;
      if(v && typeof v === 'object') flattenObjectV66(v, key, out);
      else out[key] = v;
    }
    return out;
  }
  out[prefix || 'value'] = obj;
  return out;
}

function jsonToRowsV66(text){
  const data = JSON.parse(text);
  let arr = [];
  if(Array.isArray(data)) arr = data;
  else if(data && typeof data === 'object'){
    // GeoJSON veya indeks dosyaları için sık görülen alanları tabloya çevir.
    if(Array.isArray(data.features)) arr = data.features.map((f,i)=>({sira:i+1, geometry_type:f?.geometry?.type || '', ...(f?.properties || {})}));
    else if(Array.isArray(data.files)) arr = data.files.map((x,i)=>({sira:i+1, file: typeof x === 'string' ? x : JSON.stringify(x)}));
    else arr = Object.entries(data).map(([key,value])=>({anahtar:key, deger: (value && typeof value === 'object') ? JSON.stringify(value) : value}));
  }
  const flat = arr.map(x=> flattenObjectV66(x));
  const headers = Array.from(new Set(flat.flatMap(r=>Object.keys(r))));
  return {headers, rows: flat};
}



